"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["86976"],{55608(e){e.exports=JSON.parse('{"id":"FIN-1016","slug":"tax-haven","term":"Tax Haven","also_known_as":[],"difficulty":"Intermediate","definition":"A tax haven is a country or territory with very low or zero taxes, often combined with secrecy and few requirements for real business activity, that attracts companies and individuals seeking to reduce tax elsewhere.","explanation":["Tax havens typically offer some combination of low or no corporate or income taxes, limited disclosure of who owns companies and accounts, and easy registration of companies that do little actual business locally.","Multinational companies have used tax havens to shift profits away from the countries where they make sales or carry out operations. For example, a company might move the ownership of its patents to a subsidiary in a low-tax territory, which then charges other parts of the group large royalties, shifting profits there.","Wealthy individuals have also used tax havens to hide assets and income, sometimes illegally.","International efforts have significantly reduced secrecy and profit shifting. Many countries now automatically exchange information on financial accounts held by foreign residents. The OECD\'s global minimum tax rules aim to ensure that large multinational groups pay a minimum effective rate of 15% on profits in each country. Lists of tax havens differ between organisations, and the term is often disputed by the places labelled with it."],"note":"","total":1500,"prev":{"slug":"tax-free-growth","term":"Tax-Free Growth"},"next":{"slug":"tax-incidence","term":"Tax Incidence"}}')}}]);